    {l:'j',say:'"y" as in yes',ex:'já = yah · jak = yahk',voice:'já'},
    {l:'ch',say:'a hard "h" like clearing your throat — as in Scottish "loch"',ex:'chléb = kh-lehb',voice:'chléb'}
